#!/usr/bin/env python3
"""Writes the CotonAI live-components demo styles into css/case-studies.css (between the DS-LIVE markers).

The token values are read from the real design system, not retyped:
  ~/dev/cotonai/src/design-system/tokens/tokens.css   (:root = light, .dark = dark)
They are scoped to `.dsx` / `.dsx.is-dark`, so nothing leaks into the rest of the site. The component rules
below translate the real classes in ~/dev/cotonai/src/design-system/components/* (Button, Switch, SegmentedControl,
Progress, Skeleton, StatusPill, Dialog, Tooltip, Menu) into plain CSS over those same variables.

Re-run after the tokens change:  python3 tools/build-ds-live-css.py
"""
import re, sys, pathlib

SRC = pathlib.Path.home() / "dev/cotonai/src/design-system/tokens/tokens.css"
OUT = pathlib.Path(__file__).resolve().parent.parent / "css/case-studies.css"
BEGIN, END = "/* ==== DS-LIVE:BEGIN (generated by tools/build-ds-live-css.py, do not edit by hand) ==== */", "/* ==== DS-LIVE:END ==== */"

# Only the variables the demo uses; shadcn's hsl bridge (--accent: 45 12.5% ...) has no hyphen after the group and is skipped.
KEEP = re.compile(r"^\s*--(bg|border|text|icon|accent|success|warning|danger|info|solid|loader|radius|size-control|size-focus|duration|ease|shadow|font-size|line-height|opacity)-[a-z0-9-]*:")

def block(css, start):
    i = css.index(start); j = css.index("{", i) + 1; k = css.index("\n}", j)
    return [l.rstrip() for l in css[j:k].split("\n") if KEEP.match(l)]

css = SRC.read_text()
light, dark = block(css, ":root"), block(css, "\n.dark")
assert len(light) > 100 and len(dark) > 60, (len(light), len(dark))

components = r"""
/* ---- layout ---- */
/* site.css gives every demo a fixed 960:620 clipped box (made for the Gap prototype); this one is fluid and sets its own height */
.shot--demo .cs-demo[data-case-demo="dsLive"] { aspect-ratio: auto; overflow: visible; background: none; border-radius: 0; }
.dsx { --dsx-font: Inter, "Geist", system-ui, sans-serif; font: 400 13px/20px var(--dsx-font); color: var(--text-primary); background: var(--bg-app);
  border-radius: 12px; overflow: hidden; -webkit-font-smoothing: antialiased; text-align: left;
  transition: background-color var(--duration-theme) var(--ease-standard), color var(--duration-theme) var(--ease-standard); }
.dsx *, .dsx *::before, .dsx *::after { box-sizing: border-box; }
.dsx button { font: inherit; color: inherit; }
.dsx__bar { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 10px 14px; background: var(--bg-chrome); border-bottom: 1px solid var(--border-chrome);
  transition: background-color var(--duration-theme) var(--ease-standard), border-color var(--duration-theme) var(--ease-standard); }
.dsx__title { font-size: 12px; font-weight: 500; color: var(--text-tertiary); }
.dsx__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 12px; padding: 12px; }
.dsx__tile { position: relative; overflow: hidden; display: flex; flex-direction: column; gap: 12px; min-height: 260px; padding: 14px; background: var(--bg-surface); border: 1px solid var(--border-default); border-radius: var(--radius-panel);
  transition: background-color var(--duration-theme) var(--ease-standard), border-color var(--duration-theme) var(--ease-standard); }
.dsx__k { display: flex; justify-content: space-between; gap: 8px; margin: 0; font-size: 11px; line-height: 16px; color: var(--text-tertiary); }
.dsx__k b { font-weight: 500; color: var(--text-primary); }
.dsx__row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.dsx__foot { margin: 0; padding: 0 14px 12px; font-size: 11px; line-height: 16px; color: var(--text-tertiary); }

/* ---- Button (components/button) ---- */
.dsx-btn { position: relative; display: inline-flex; flex: none; align-items: center; justify-content: center; gap: 6px; height: var(--size-control-default); padding: 0 12px; border: 1px solid transparent; border-radius: var(--radius-control);
  background: transparent; color: var(--text-primary); font-weight: 500; font-size: 13px; line-height: 1; white-space: nowrap; cursor: pointer; user-select: none; outline: none;
  transition: background-color var(--duration-fast), border-color var(--duration-fast), color var(--duration-fast); }
.dsx-btn:focus-visible, .dsx-ib:focus-visible, .dsx-seg button:focus-visible, .dsx-sw:focus-visible, .dsx-row:focus-visible { outline: var(--size-focus-width) solid var(--border-focus); outline-offset: var(--size-focus-offset); }
.dsx-btn:disabled { opacity: var(--opacity-disabled, .5); pointer-events: none; }
.dsx-btn[aria-busy="true"] { cursor: progress; }
.dsx-btn--primary { background: var(--accent-default); color: var(--text-on-accent); }
.dsx-btn--primary:hover { background: var(--accent-hover); } .dsx-btn--primary:active { background: var(--accent-pressed); }
.dsx-btn--secondary { border-color: var(--accent-default); background: var(--accent-subtle); }
.dsx-btn--secondary:hover { background: var(--accent-subtle-hover); } .dsx-btn--secondary:active { background: var(--accent-subtle-pressed); }
.dsx-btn--neutral { border-color: var(--border-chrome); background: var(--bg-chrome); }
.dsx-btn--neutral:hover { background: var(--bg-chrome-hover); } .dsx-btn--neutral:active { background: var(--bg-chrome-pressed); }
.dsx-btn--solid { border-color: var(--border-input); background: var(--bg-solid); }
.dsx-btn--solid:hover { border-color: var(--solid-border-hover); background: var(--bg-solid-hover); } .dsx-btn--solid:active { background: var(--bg-solid-pressed); }
.dsx-btn--ghost { color: var(--text-tertiary); }
.dsx-btn--ghost:hover { background: var(--bg-control); color: var(--text-primary); } .dsx-btn--ghost:active { background: var(--bg-control-pressed); }
.dsx-btn--danger { border-color: var(--danger-default); color: var(--danger-fg); }
.dsx-btn--danger:hover { background: var(--danger-subtle); color: var(--text-primary); } .dsx-btn--danger:active { border-color: var(--danger-pressed); background: var(--danger-subtle-pressed); }
.dsx-spin { width: 16px; height: 16px; flex: none; animation: dsx-spin 1s linear infinite; }
.dsx-spin--sm { width: 12px; height: 12px; }
.dsx-ib { display: inline-grid; place-items: center; width: var(--size-control-icon); height: var(--size-control-icon); padding: 0; border: 1px solid var(--border-chrome); border-radius: var(--radius-control);
  background: var(--bg-chrome); color: var(--icon-active); cursor: pointer; outline: none; transition: background-color var(--duration-fast), border-color var(--duration-fast); }
.dsx-ib:hover { background: var(--bg-chrome-hover); } .dsx-ib:active { background: var(--bg-chrome-pressed); } .dsx-ib svg { width: 16px; height: 16px; }

/* ---- Switch (components/switch) ---- */
.dsx-sw-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; font-size: 13px; }
.dsx-sw { display: inline-flex; flex: none; align-items: center; width: 36px; height: 20px; padding: 2px; border: 1px solid var(--border-control); border-radius: 9999px; background: var(--bg-control-pressed); cursor: pointer; outline: none;
  transition: background-color var(--duration-fast), border-color var(--duration-fast); }
.dsx-sw:hover { background: var(--bg-control-hover); }
.dsx-sw i { display: block; width: 14px; height: 14px; border-radius: 9999px; background: currentColor; color: var(--text-tertiary); transition: transform var(--duration-fast), color var(--duration-fast); }
.dsx-sw[aria-checked="true"] { border-color: var(--accent-default); background: var(--accent-default); } .dsx-sw[aria-checked="true"]:hover { background: var(--accent-hover); }
.dsx-sw[aria-checked="true"] i { transform: translateX(16px); color: var(--text-on-accent); }

/* ---- SegmentedControl, track variant (components/segmented-control) ---- */
.dsx-seg { display: inline-flex; height: var(--size-control-default); padding: 2px; gap: 2px; border-radius: var(--radius-control); background: var(--bg-control); }
.dsx-seg button { display: inline-flex; align-items: center; justify-content: center; padding: 0 12px; border: 1px solid transparent; border-radius: var(--radius-control); background: none; color: var(--text-tertiary);
  font-weight: 500; font-size: 13px; line-height: 1; cursor: pointer; outline: none; transition: background-color var(--duration-fast), border-color var(--duration-fast), color var(--duration-fast); }
.dsx-seg button:hover { color: var(--toggle-fg-hover, var(--text-primary)); }
.dsx-seg button[aria-checked="true"] { border-color: var(--border-default); background: var(--bg-selected); color: var(--text-primary); }
.dsx-seg--sm { height: var(--size-control-dense); } .dsx-seg--sm button { padding: 0 10px; font-size: 12px; }

/* ---- StatusPill (components/status-pill) ---- */
.dsx-pill { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 8px; border: 1px solid var(--border-default); border-radius: 9999px; background: var(--bg-chrome); color: var(--text-primary); font-size: 12px; font-weight: 500; line-height: 1; white-space: nowrap;
  transition: background-color var(--duration-base), border-color var(--duration-base), color var(--duration-base); }
.dsx-pill--accent { border-color: var(--accent-default); background: var(--accent-subtle); }
.dsx-pill--warning { border-color: var(--warning-default); background: var(--warning-subtle); color: var(--warning-fg); }
.dsx-pill--danger { border-color: var(--danger-default); background: var(--danger-subtle); color: var(--danger-fg); }

/* ---- Progress + Skeleton (components/progress, components/skeleton) ---- */
.dsx-bar { position: relative; width: 100%; height: 4px; overflow: hidden; border-radius: 9999px; background: var(--bg-control-pressed); }
.dsx-bar i { display: block; width: 100%; height: 100%; background: var(--accent-default); transform: translateX(-100%); transform-origin: left; transition: transform var(--duration-base) ease-out; }
.dsx-gen__stage { position: relative; display: grid; place-items: center; height: 132px; overflow: hidden; border-radius: var(--radius-control); background: var(--bg-control); color: var(--text-tertiary); font-size: 12px; text-align: center;
  transition: background-color var(--duration-theme) var(--ease-standard); }
.dsx-gen__sk { position: absolute; inset: 0; background: var(--bg-control-hover); opacity: 0; animation: dsx-pulse 2s cubic-bezier(.4, 0, .6, 1) infinite; transition: opacity var(--duration-base); }
.dsx-gen__img { position: absolute; inset: 0; background: linear-gradient(135deg, #EBD9C6, #CDA98C 45%, #8D7059); opacity: 0; transform: scale(1.03); transition: opacity var(--duration-slow) var(--ease-emphasized), transform var(--duration-slow) var(--ease-emphasized); }
.dsx-gen__txt { position: relative; }
.dsx-gen__stage[data-phase="queued"] .dsx-gen__sk, .dsx-gen__stage[data-phase="running"] .dsx-gen__sk { opacity: 1; }
.dsx-gen__stage[data-phase="done"] .dsx-gen__img { opacity: 1; transform: none; }
.dsx-gen__stage[data-phase="done"] .dsx-gen__txt { color: #fff; text-shadow: 0 1px 2px #0006; }
.dsx-gen__meta { display: flex; align-items: center; justify-content: space-between; gap: 8px; }

/* ---- Menu (components/menu), Tooltip (components/tooltip), Dialog (components/dialog) ---- */
.dsx-pop { position: relative; }
.dsx-menu { position: absolute; z-index: 2; top: calc(100% + 6px); left: 0; min-width: 176px; padding: 4px; border: 1px solid var(--border-shell); border-radius: var(--radius-panel); background: var(--bg-surface-raised); box-shadow: var(--shadow-popover);
  opacity: 0; transform: translateY(-4px); pointer-events: none; transition: opacity var(--duration-base) var(--ease-standard), transform var(--duration-base) var(--ease-standard); }
.dsx-menu[data-state="open"] { opacity: 1; transform: none; pointer-events: auto; }
.dsx-row { display: flex; align-items: center; gap: 8px; width: 100%; height: 28px; padding: 0 8px; border: 0; border-radius: 8px; background: none; color: var(--text-primary); font-size: 12px; line-height: 1; text-align: left; cursor: default; outline: none; }
.dsx-row:hover, .dsx-row:focus-visible { background: var(--bg-control-hover); }
.dsx-row kbd { margin-left: auto; padding-left: 24px; color: var(--text-tertiary); font: inherit; font-size: 11px; }
.dsx-row--danger { color: var(--danger-fg); } .dsx-row--danger:hover { background: var(--danger-subtle); }
.dsx-sep { height: 1px; margin: 4px -4px; background: var(--border-shell); }
.dsx-tip { position: absolute; z-index: 2; bottom: calc(100% + 8px); left: 50%; padding: 6px 10px; border-radius: var(--radius-control); background: var(--bg-surface); box-shadow: var(--shadow-panel); font-size: 12px; line-height: 16px; white-space: nowrap; pointer-events: none;
  opacity: 0; transform: translate(-50%, 2px); transition: opacity var(--duration-base) var(--ease-standard) .25s, transform var(--duration-base) var(--ease-standard) .25s; }
.dsx-tip span { margin-left: 8px; color: var(--text-tertiary); font-size: 11px; }
.dsx-pop:hover .dsx-tip, .dsx-pop:focus-within .dsx-tip { opacity: 1; transform: translate(-50%, 0); }
.dsx-pop:has(.dsx-menu[data-state="open"]) .dsx-tip { opacity: 0; }
.dsx-scrim { position: absolute; inset: 0; z-index: 3; display: grid; place-items: center; padding: 16px; background: var(--bg-scrim); opacity: 0; pointer-events: none; transition: opacity 150ms ease-out; }
.dsx-scrim[data-state="open"] { opacity: 1; pointer-events: auto; }
.dsx-dlg { width: min(100%, 280px); padding: 16px; border: 1px solid var(--border-default); border-radius: var(--radius-panel); background: var(--bg-surface-raised); box-shadow: var(--shadow-overlay); transform: scale(.95); transition: transform 150ms ease-out; }
.dsx-scrim[data-state="open"] .dsx-dlg { transform: none; }
.dsx-dlg h4 { margin: 0 0 4px; font-size: 14px; font-weight: 500; line-height: 20px; } .dsx-dlg p { margin: 0 0 16px; color: var(--text-secondary); font-size: 12px; line-height: 16px; }
.dsx-dlg .dsx__row { justify-content: flex-end; }

/* ---- Agent states (patterns/agent) ---- */
.dsx-ag { display: flex; align-items: center; gap: 8px; min-height: 28px; font-size: 12px; color: var(--text-secondary); }
.dsx-dot { position: relative; width: 8px; height: 8px; flex: none; border-radius: 9999px; background: var(--accent-default); }
.dsx-dot::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: var(--accent-default); opacity: .4; animation: dsx-ping 1s cubic-bezier(0, 0, .2, 1) infinite; }
.dsx-think { animation: dsx-pulse 2s cubic-bezier(.4, 0, .6, 1) infinite; }
.dsx-stream { min-height: 40px; margin: 0; font-size: 13px; line-height: 20px; color: var(--text-primary); }
.dsx-cur { display: inline-block; width: 6px; height: 14px; margin-left: 2px; background: currentColor; transform: translateY(2px); animation: dsx-pulse 1s cubic-bezier(.4, 0, .6, 1) infinite; }

@keyframes dsx-spin { to { transform: rotate(360deg); } }
@keyframes dsx-pulse { 50% { opacity: .5; } }
@keyframes dsx-ping { 75%, 100% { transform: scale(2.2); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .dsx *, .dsx *::before, .dsx *::after { animation: none !important; transition: none !important; } }
"""

gen = "\n".join([BEGIN, "/* Source: ~/dev/cotonai/src/design-system/tokens/tokens.css. Light is :root, dark is .dark. */",
                 ".dsx {", *light, "}", ".dsx.is-dark {", *dark, "}", components.strip("\n"), END])
cur = OUT.read_text()
if BEGIN in cur:
    cur = re.sub(re.escape(BEGIN) + r".*?" + re.escape(END), lambda m: gen, cur, flags=re.S)
else:
    cur = cur.rstrip("\n") + "\n\n" + gen + "\n"
OUT.write_text(cur)
print(f"wrote {len(light)} light + {len(dark)} dark token vars and the component rules into {OUT.name}")
